def house_robber_ii(nums):
    def rob_line(arr):
        dp = [0] * (len(arr) + 1)
        for i, x in enumerate(arr):
            dp[i + 1] = max(dp[i], (dp[i - 1] if i >= 1 else 0) + x)
        return dp[len(arr)]
    n = len(nums)
    if n == 1:
        return nums[0]
    return max(rob_line(nums[:-1]), rob_line(nums[1:]))
